INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'Physics', 'Unit 6', 'Molarum Grade 10 — Physics Electromagnetic Waves and Geometrical Optics', 'Source-grounded Molarum Grade 10 Physics questions for Electromagnetic Waves and Geometrical Optics.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('00a92f41-8ecb-47ae-8715-3c0a92c2eb5d'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which of the following is an electromagnetic wave?', 'Radio wave', 'Electromagnetic waves propagate through space without a medium; sound, water, and seismic waves are mechanical waves.', 0),('c0701196-1488-407c-84fa-e08d042cdeac'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which EM wave has the longest wavelength?', 'Radio waves', 'Radio waves have longer wavelengths than visible, ultraviolet, and gamma rays.', 1),('a5530bb0-6f1f-46c3-87ba-9afd8bed43fc'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'A ray of light enters from air into glass with incidence angle 60° and refracted angle 40°. The refractive index of glass (n2) is approximately?', '1.35', 'Using Snell''s law n1 sin θ1 = n2 sin θ2; with n1 ≈ 1 and θ1=60°, θ2=40°, n2 ≈ sin60°/sin40° ≈ 0.866/0.643 ≈ 1.35.', 2),('3972b6f9-268a-4d70-8d19-a5e550422187'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which statement about plane and convex mirrors is true?', 'Plane mirrors form a virtual image behind the mirror', 'Plane mirrors always form virtual, erect images behind the mirror. Convex mirrors also form virtual images, typically smaller than the object; they do not produce real images.', 3),('ec7e586e-4ed0-4545-81f4-1c94b74124dd'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'In a double-slit setup, slit separation d = 0.40 mm, screen distance L = 2.0 m. The distance between adjacent bright fringes on the screen is 5.0 mm. What is the wavelength of the light?', 'Option A', 'For bright fringes m=1, spacing δy ≈ λL/d, so λ ≈ δy d / L = 0.005 m * 0.00040 m / 2.0 m = 1.0 x 10^-6 m = 1.0 μm.', 4),('6041f61c-4651-4e74-8229-4186fbe78d29'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'true_false', 'A plane mirror always forms a real image.', 'False', 'Plane mirrors form virtual images behind the mirror; real images are produced by curved mirrors under appropriate conditions.', 5),('74eb1b7e-4a7e-4d9f-8d7b-b4b200c4cd36'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'Define focal length in the context of a converging (concave) lens or mirror.', 'Focal length is the distance from the mirror or lens to the focal point along the principal axis; for a concave mirror or converging lens, the focal point lies in front of the mirror or on the principal axis in front for a lens.', 'Focal length relates object and image formation in spherical mirrors and lenses; positive for converging systems.', 6),('1b9c95bc-1a58-488a-8ff2-85f36ee048b2'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'Briefly explain how the eye changes focal length to focus on near versus distant objects.', 'The eye adjusts the curvature of the lens via the ciliary muscles to increase or decrease its optical power (focal length). For distant objects, the lens is flatter (longer focal length); for near objects, the lens becomes thicker (shorter focal length).', 'Accommodation adjusts focusing by changing the lens shape, aided by the suspensory ligaments and ciliary muscles.', 7),('0a805494-41b9-4436-8674-6f5631c32431'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'A light wave with wavelength 600 nm travels in vacuum. Calculate its frequency. Provide the result with units.', '5.0 x 10^14 Hz', 'Frequency f is related to wavelength by f = c/λ; c ≈ 3.00 x 10^8 m/s, λ = 600 nm = 6.00 x 10^-7 m; f ≈ 3.00 x 10^8 / 6.00 x 10^-7 = 5.0 x 10^14 Hz.', 8),('abd98045-2418-4cc2-8766-7f24bc296cf1'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'A converging lens has object distance u = 20 cm and image distance v = 40 cm. Use the lens formula to find the focal length f of the lens. State the final answer with units.', '13.3 cm', 'Lens formula 1/f = 1/v + 1/u = 1/40 + 1/20 = 0.075; f = 1/0.075 ≈ 13.3 cm.', 9),('281ea919-8cba-4eb0-81bc-9d39f46e027e'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which statement about electromagnetic waves in vacuum is true?', 'They propagate at the speed of light in vacuum, approximately 3 x 10^8 m/s.', 'In vacuum, EM waves propagate at the universal speed c; no medium is required.', 10),('0f4ea679-f55a-4faf-8441-722099199343'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which electromagnetic waves have the longest wavelength?', 'Radio waves', 'Radio waves occupy the longest wavelengths in the EM spectrum among common categories.', 11),('761daa7b-1cba-4cc5-82ec-fe93d97ba5bb'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which phenomenon demonstrates the wave nature of light?', 'Diffraction and interference', 'Diffraction and interference are classic wave phenomena in light.', 12),('f85fa0ed-2442-4640-8d04-4f0b1c4a4536'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which statement best describes refraction?', 'Light changes speed and bends when crossing a boundary', 'Refraction occurs due to change in speed as light passes between media, causing bending.', 13),('8c3a15a3-f666-4cda-82fa-e31e31148ed8'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'A concave mirror forms a real image when the object is beyond the focal point.', 'True', 'For a concave mirror, when the object is beyond the focal point, a real image is formed on the same side as the object.', 14),('189ec152-5887-4708-82e5-b731697dc271'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'true_false', 'The primary colors of light are red, green, and blue.', 'True', 'Additive color mixing uses red, green, and blue as primaries to produce other colors including white.', 15),('502853e6-0704-417e-80da-9e4b3223c750'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'Explain additive color mixing in human vision.', 'Additive color mixing combines red, green, and blue light; the brain perceives white when all three are present at sufficient intensities; different ratios produce other colors.', 'In additive color mixing, lights of different colors add their wavelengths to create new colors.', 16),('db53a2ac-d078-4c6c-8051-0e31f35ceb01'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'Describe how colored filters subtract colors from white light and how this affects the color seen.', 'Filters transmit only certain wavelengths and absorb the rest; the color seen is the color of the transmitted wavelengths; if no light is transmitted, the result appears black.', 'Filters reduce the spectrum by selective transmission, altering the perceived color.', 17),('d5b2f820-6e49-4372-8e9b-52285cf08d1a'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'A light ray travels from air (n1 = 1.00) into a glass block (n2 = 1.50) with an incidence angle of 30°. Calculate the angle of refraction inside the glass.', '≈19.5°', 'Using Snell''s law n1 sin i = n2 sin r, sin r = (n1/n2) sin i = (1/1.50) * sin(30°) = 0.333..., r ≈ 19.5°.', 18),('da8cad8e-845b-41c2-8671-cd320ae3af5d'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'A thin converging lens with focal length f = 15 cm forms an image of an object placed at u = 25 cm. Calculate the image distance v and the magnification m.', 'v ≈ 9.375 cm; m ≈ -0.375', 'Using lens formula 1/f = 1/v - 1/u => 1/v = 1/f + 1/u = 1/15 + 1/25 = 8/75, v ≈ 9.375 cm. Magnification m = -v/u = -9.375/25 ≈ -0.375.', 19),('1d7db57e-2c99-4e54-8e39-6cbb70eef32d'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which of the following is not an electromagnetic wave?', 'sound waves', 'Electromagnetic waves include radio, microwave, infrared, visible, ultraviolet, X-ray, and gamma rays. Sound is a mechanical wave.', 20),('91294212-38ac-4389-8714-02785cccd4b5'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which portion of the electromagnetic spectrum has the longest wavelength?', 'Radio waves', 'In the EM spectrum, wavelength decreases from radio to gamma; radio waves have the longest wavelengths.', 21),('acbf437c-1a09-4e6a-8379-8a42cd6bb276'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'A light ray entering from air into water slows down and bends toward the normal.', 'True', 'When light crosses from a less dense to a denser medium, its speed decreases and it refracts toward the normal.', 22),('c23494ba-2a38-41f6-8992-b3d554c5e8b3'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'A concave mirror forms a real image when the object is placed beyond the focal point. Which statement is true?', 'Image is real and inverted', 'Beyond the focal point, a concave mirror produces a real, inverted image on the opposite side of the mirror.', 23),('65d297a5-1e01-430e-8c98-197be188f2bb'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which statement correctly describes a fundamental property that allows electromagnetic waves to propagate in vacuum?', 'They consist of oscillating electric and magnetic fields perpendicular to each other and to the direction of travel', 'EM waves propagate as changing E and B fields; no medium is required for propagation in vacuum.', 24),('44d086f5-386d-4b6a-8390-363944bef5d4'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'true_false', 'Light can travel faster in water than in air.', 'False', 'Light travels slower in denser media; air has a lower refractive index than water, so it travels faster in air.', 25),('5e44f709-3497-4ab0-89b6-a4f711a270b4'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'State the law of reflection.', 'Angle of incidence equals angle of reflection.', 'The angle at which the incoming ray strikes the surface equals the angle at which it reflects, measured with respect to the normal to the surface.', 26),('d47abedf-c564-44f8-8b8a-39934d9afd3d'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'Describe how a plane mirror forms an image and whether the image is virtual or real.', 'A plane mirror forms a virtual image located behind the mirror; the image is upright and the same size as the object.', 'Plane mirrors always produce virtual, erect images that are laterally reversed relative to the object and appear to be behind the mirror.', 27),('72b8df63-3dfb-4411-8afc-f1f03162bdb3'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'A light ray travels from air (n = 1.00) into water (n = 1.33) with incident angle i = 30°. Use Snell''s law to calculate the refracted angle r. Provide all steps and final answer with units.', 'Approximately 22.0°', 'Using Snell''s law n1 sin i = n2 sin r; sin r = (n1/n2) sin i = (1.00/1.33) × sin 30° ≈ 0.376; r ≈ arcsin(0.376) ≈ 22.0°.', 28),('66d22a86-fd77-4706-8a0a-4f9846271f47'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'A converging lens with focal length f = 10 cm forms an image of an object placed 20 cm in front of the lens. Use the lens formula to find the image distance v. Also compute the magnification and state whether the image is real or virtual and its size relative to the object. Provide full steps and final units.', 'v = 20 cm; magnification m = +1; image is real and same size as the object, located 20 cm on the opposite side of the lens.', 'Using lens formula 1/f = 1/v + 1/u; with f=+10 cm, u=+20 cm, 1/v = 1/f - 1/u = 0.1 - 0.05 = 0.05 → v = 20 cm. Magnification m = v/u = 20/20 = 1.', 29),('3d5bbdf8-dc8b-4d0e-811b-82c7c25f4775'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which statement about electromagnetic waves is correct?', 'They can travel in vacuum and in matter.', 'EM waves do not require a medium and can transfer energy through both vacuum and materials; their speed in vacuum is c, and in materials slower depending on the medium.', 30),('192d599f-77a0-40fa-8953-f0647c20c4e2'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which region of the electromagnetic spectrum has the longest wavelength?', 'Radio waves', 'Radio waves have wavelengths longer than microwaves, infrared, visible, ultraviolet, X-ray, etc.', 31),('a7046af4-8c57-4d67-87c6-ee3c9038f00e'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'true_false', 'EM waves can travel through a vacuum.', 'True', 'Electromagnetic waves propagate through vacuum at speed c.', 32),('7f0749af-eb28-4dd2-8e6c-d86894be578b'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'When light passes from air into water (n increases), the ray bends toward the normal.', 'It bends toward the normal when entering a denser medium.', 'Snell''s law: n1 sinθ1 = n2 sinθ2; increasing n2 causes θ2 to be smaller (closer to normal).', 33),('2bbce142-4a05-4519-8ab6-2e93a0563dbd'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'Which type of lens forms a real image of a distant object?', 'Convex lens', 'A converging lens (convex) can form a real image of distant objects on a screen.', 34),('74b9a759-cfe3-4b74-8952-baa5bd88e090'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'State Snell''s law and define refractive index.', 'Snell''s law: n1 sin(theta1) = n2 sin(theta2); refractive index n = c/v (or n = sin(theta2)/sin(theta1) for the interface).', 'Snell''s law relates incident and refracted angles via indices of refraction; refractive index is the ratio of light speeds or the sine relationship between angles.', 35),('210dbf05-9761-40f4-843d-c94982123acf'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'multiple_choice', 'In additive color mixing, which combination produces white light?', 'Red + Green + Blue', 'White is produced by combining all three primary colors of light in additive mixing.', 36),('7cd4df56-8724-4dcc-8290-f74695663700'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'A green light has a wavelength of 550 nm in vacuum. What is its frequency? Provide all steps and final answer with units.', 'Frequency ≈ 5.45 × 10^14 Hz', 'f = c/λ; with c = 3.00 × 10^8 m/s and λ = 550 × 10^-9 m, f ≈ 5.45 × 10^14 Hz.', 37),('bd406c08-66bf-4049-8259-44626d74a97b'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'A convex lens has object distance u = 20 cm and image distance v = 30 cm. Using the lens formula 1/f = 1/v + 1/u, calculate the focal length f. Provide the steps and final answer with units.', 'f = 12 cm', 'Using 1/f = 1/v + 1/u = 1/30 + 1/20 = 5/60 = 1/12, hence f = 12 cm.', 38),('c58587e7-3d53-4180-8d22-7ea321bcc0b6'::uuid, '32dd8119-a107-4fb8-878e-5a3d79170c5f'::uuid, 'fill_blank', 'Briefly describe how the eye focuses light on the retina and the role of the lens.', 'The eye focuses by changing the lens shape (accommodation) via ciliary muscles; the lens curvature increases for near objects and decreases for distant objects to focus light on the retina.', 'Lens accommodation adjusts focal length so the image falls on the retina; cornea plus lens form the image.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
